  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `order_no` varchar(60) NOT NULL DEFAULT '' COMMENT '订单编号',
  `order_detail_no` varchar(60) NOT NULL DEFAULT '' COMMENT '订单明细编号',
  `product_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '商品id',
  `product_name` varchar(60) DEFAULT '' COMMENT '商品名称',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '订单状态',
  `status_desc` varchar(60) DEFAULT '' COMMENT '状态描述',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2995 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='订单记录';

-- ----------------------------
-- Records of order_status_record
-- ----------------------------

-- ----------------------------
-- Table structure for product
-- ----------------------------
DROP TABLE IF EXISTS `product`;
CREATE TABLE `product` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '创建人',
  `update_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '更新人',
  `delete_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT '删除标志',
  `product_id` bigint(20) DEFAULT '0' COMMENT '商品id',
  `category_id` bigint(20) DEFAULT '0' COMMENT '品类id',
  `name` varchar(60) DEFAULT '' COMMENT '商品名称',
  `sub_title` varchar(100) DEFAULT '' COMMENT '简要描述',
  `main_image` varchar(100) DEFAULT '' COMMENT '商品图片地址',
  `sub_images` varchar(2000) DEFAULT '' COMMENT '子图片列表',
  `activity_id` bigint(20) DEFAULT NULL COMMENT '活动id',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '商品状态',
  `price` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '商品单价',
  `stock` int(11) NOT NULL DEFAULT '0' COMMENT '库存数',
  `hot_flag` tinyint(4) DEFAULT NULL COMMENT '热门',
  `shop_id` bigint(20) DEFAULT NULL COMMENT '所属店铺ID',
  `is_blind_box` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否为盲盒商品：0-否，1-是',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_shop_id` (`shop_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10000 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='商品';

-- ----------------------------
-- Records of product
-- ----------------------------

-- ----------------------------
-- Table structure for product_comment
-- ----------------------------
DROP TABLE IF EXISTS `product_comment`;
CREATE TABLE `product_comment` (
  `comment_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `product_id` bigint(20) NOT NULL COMMENT '商品ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `order_id` bigint(20) DEFAULT NULL COMMENT '订单ID（可选）',
  `parent_id` bigint(20) DEFAULT '0' COMMENT '父评论ID（用于回复）',
  `content` text NOT NULL COMMENT '评论内容',
  `images` json DEFAULT NULL COMMENT '评论图片',
  `score` tinyint(4) NOT NULL DEFAULT '5' COMMENT '评分（1-5星）',
  `is_anonymous` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否匿名（0-否，1-是）',
  `like_count` int(11) NOT NULL DEFAULT '0' COMMENT '点赞数',
  `reply_count` int(11) NOT NULL DEFAULT '0' COMMENT '回复数',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态（1-正常，2-审核中，3-已删除）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '评论时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`comment_id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_product_score` (`product_id`,`score`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品评论表';

-- ----------------------------
-- Records of product_comment
-- ----------------------------

-- ----------------------------
-- Table structure for recharge_info
-- ----------------------------
DROP TABLE IF EXISTS `recharge_info`;
CREATE TABLE `recharge_info` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `user_id` bigint(20) DEFAULT NULL COMMENT '用户ID',
  `balance` decimal(20,2) DEFAULT NULL COMMENT '金额',
  `order_id` bigint(20) DEFAULT NULL COMMENT '订单id',
  `order_no` varchar(60) DEFAULT NULL COMMENT '订单编号',
  `status` tinyint(4) DEFAULT '1' COMMENT '充值状态：1-待支付 2-支付成功 3-支付失败 4-已退款',
  `payment_type` tinyint(4) DEFAULT '1' COMMENT '支付方式：1-支付宝 2-微信 3-余额 4-银行卡',
  `payment_time` datetime DEFAULT NULL COMMENT '支付时间',
  `payment_no` varchar(64) DEFAULT '' COMMENT '支付流水号',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`),
  KEY `idx_order_no` (`order_no`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=280 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of recharge_info
-- ----------------------------

-- ----------------------------
-- Table structure for refund_record
-- ----------------------------
DROP TABLE IF EXISTS `refund_record`;
CREATE TABLE `refund_record` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '创建人',
  `update_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '更新人',
  `delete_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT '删除标志',
  `refund_no` varchar(60) NOT NULL DEFAULT '' COMMENT '退款单号',
  `order_no` varchar(60) NOT NULL DEFAULT '' COMMENT '订单编号',
  `user_id` bigint(20) NOT NULL DEFAULT '0' COMMENT '用户ID',
  `refund_amount` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '退款金额',
  `refund_status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '退款状态：1-申请中 2-处理中 3-退款成功 4-退款失败 5-已拒绝',
  `refund_status_desc` varchar(20) NOT NULL DEFAULT '' COMMENT '退款状态描述',
  `refund_reason` varchar(500) DEFAULT '' COMMENT '退款原因',
  `audit_opinion` varchar(500) DEFAULT '' COMMENT '审核意见',
  `refund_type` tinyint(4) DEFAULT '1' COMMENT '退款方式：1-原路退回 2-余额退回',
  `refund_time` datetime DEFAULT NULL COMMENT '退款时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_refund_no` (`refund_no`) USING BTREE,
  KEY `idx_order_no` (`order_no`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='退款记录';

-- ----------------------------
-- Records of refund_record
-- ----------------------------

-- ----------------------------
-- Table structure for shop
-- ----------------------------
DROP TABLE IF EXISTS `shop`;
CREATE TABLE `shop` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '创建人',
  `update_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '更新人',
  `delete_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT '删除标志',
  `user_id` bigint(20) NOT NULL COMMENT '店铺所有者用户ID',
  `shop_name` varchar(100) NOT NULL COMMENT '店铺名称',
  `shop_logo` varchar(200) DEFAULT '' COMMENT '店铺logo',
  `shop_banner` varchar(200) DEFAULT '' COMMENT '店铺横幅',
  `description` varchar(500) DEFAULT '' COMMENT '店铺描述',
  `contact_phone` varchar(20) DEFAULT '' COMMENT '联系电话',
  `contact_address` varchar(200) DEFAULT '' COMMENT '联系地址',
  `shop_score` decimal(3,2) DEFAULT '5.00' COMMENT '店铺评分',
  `sales_count` int(11) DEFAULT '0' COMMENT '销售数量',
  `product_count` int(11) DEFAULT '0' COMMENT '商品数量',
  `follower_count` int(11) DEFAULT '0' COMMENT '粉丝数量',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '店铺状态 1:正常 2:关闭 3:审核中',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_shop_name` (`shop_name`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='店铺信息';

