-- ----------------------------
-- Table structure for user_address
-- ----------------------------
DROP TABLE IF EXISTS `user_address`;
CREATE TABLE `user_address` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `address_id` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '地址id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `create_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '创建人',
  `update_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '更新人',
  `delete_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT '删除标志',
  `default_flag` tinyint(4) DEFAULT '0' COMMENT '默认标志',
  `receive_name` varchar(60) NOT NULL DEFAULT '' COMMENT '收货人',
  `receive_phone` varchar(20) NOT NULL DEFAULT '' COMMENT '联系号码',
  `province` varchar(20) NOT NULL DEFAULT '' COMMENT '省份',
  `province_code` varchar(10) NOT NULL DEFAULT '' COMMENT '省份编码',
  `city` varchar(20) NOT NULL DEFAULT '' COMMENT '城市',
  `city_code` varchar(10) NOT NULL DEFAULT '' COMMENT '城市编码',
  `area` varchar(20) NOT NULL DEFAULT '' COMMENT '区',
  `area_code` varchar(10) NOT NULL DEFAULT '' COMMENT '区编码',
  `street` varchar(100) DEFAULT '' COMMENT '详细地址',
  `postal_code` varchar(10) DEFAULT '' COMMENT '邮编',
  `address_label` tinyint(4) DEFAULT '0' COMMENT '地址标签',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='用户地址';

-- ----------------------------
-- Records of user_address
-- ----------------------------

-- ----------------------------
-- Table structure for user_favorite
-- ----------------------------
DROP TABLE IF EXISTS `user_favorite`;
CREATE TABLE `user_favorite` (
  `favorite_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '收藏ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `target_type` tinyint(4) NOT NULL COMMENT '收藏类型(1-商品 2-店铺)',
  `target_id` bigint(20) NOT NULL COMMENT '目标ID(商品ID或店铺ID)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  PRIMARY KEY (`favorite_id`),
  UNIQUE KEY `uniq_user_target` (`user_id`,`target_type`,`target_id`),
  KEY `idx_target_type_id` (`target_type`,`target_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户收藏表';

-- ----------------------------
-- Records of user_favorite
-- ----------------------------

-- ----------------------------
-- Table structure for user_footprint
-- ----------------------------
DROP TABLE IF EXISTS `user_footprint`;
CREATE TABLE `user_footprint` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '创建人',
  `update_user` bigint(20) NOT NULL DEFAULT '0' COMMENT '更新人',
  `delete_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT '删除标志',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID（关联sys_user.user_id）',
  `target_type` tinyint(4) NOT NULL COMMENT '浏览类型(1-商品 2-店铺 3-活动)',
  `target_id` bigint(20) NOT NULL COMMENT '目标ID（商品ID/店铺ID/活动ID）',
  `target_name` varchar(100) NOT NULL DEFAULT '' COMMENT '目标名称',
  `target_image` varchar(200) DEFAULT '' COMMENT '目标图片',
  `price` decimal(20,2) DEFAULT NULL COMMENT '价格（如果是商品）',
  `category_id` bigint(20) DEFAULT NULL COMMENT '分类ID',
  `category_name` varchar(50) DEFAULT '' COMMENT '分类名称',
  `browse_count` int(11) NOT NULL DEFAULT '1' COMMENT '浏览次数',
  `last_browse_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后浏览时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_user_target` (`user_id`,`target_type`,`target_id`) COMMENT '用户-目标唯一索引',
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_target_type_id` (`target_type`,`target_id`) USING BTREE,
  KEY `idx_last_browse_time` (`last_browse_time`) USING BTREE,
  KEY `idx_user_browse_time` (`user_id`,`last_browse_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='用户足迹表';

-- ----------------------------
-- Records of user_footprint
-- ----------------------------
