INSERT INTO `user19` VALUES ('  `activity_id` bigint DEFAULT \'0\' COMMENT \'活动id\',');
INSERT INTO `user19` VALUES ('  `activity_name` varchar(50) DEFAULT \'\' COMMENT \'活动名称\',');
INSERT INTO `user19` VALUES ('  `activity_main_image` varchar(100) DEFAULT \'\' COMMENT \'活动图片地址\',');
INSERT INTO `user19` VALUES ('  `product_id` bigint NOT NULL DEFAULT \'0\' COMMENT \'商品id\',');
INSERT INTO `user19` VALUES ('  `product_name` varchar(50) NOT NULL DEFAULT \'\' COMMENT \'商品名称\',');
INSERT INTO `user19` VALUES ('  `product_main_image` varchar(100) NOT NULL DEFAULT \'\' COMMENT \'商品图片地址\',');
INSERT INTO `user19` VALUES ('  `current_unit_price` decimal(20,2) DEFAULT \'0.00\' COMMENT \'单价\',');
INSERT INTO `user19` VALUES ('  `quantity` int DEFAULT \'0\' COMMENT \'数量\',');
INSERT INTO `user19` VALUES ('  `total_price` decimal(20,2) DEFAULT \'0.00\' COMMENT \'总价\',');
INSERT INTO `user19` VALUES ('  `user_id` bigint NOT NULL DEFAULT \'0\' COMMENT \'购买人id\',');
INSERT INTO `user19` VALUES ('  `status` tinyint NOT NULL DEFAULT \'0\' COMMENT \'订单状态\',');
INSERT INTO `user19` VALUES ('  `status_desc` varchar(20) DEFAULT \'\' COMMENT \'状态描述\',');
