INSERT INTO `user19` VALUES ('  `province_code` varchar(10) NOT NULL DEFAULT \'\' COMMENT \'省份编码\',');
INSERT INTO `user19` VALUES ('  `city` varchar(20) NOT NULL DEFAULT \'\' COMMENT \'城市\',');
INSERT INTO `user19` VALUES ('  `city_code` varchar(10) NOT NULL DEFAULT \'\' COMMENT \'城市编码\',');
INSERT INTO `user19` VALUES ('  `area` varchar(20) NOT NULL DEFAULT \'\' COMMENT \'区\',');
INSERT INTO `user19` VALUES ('  `area_code` varchar(10) NOT NULL DEFAULT \'\' COMMENT \'区编码\',');
