INSERT INTO `user19` VALUES ('  `postal_code` varchar(10) DEFAULT \'\' COMMENT \'邮编\',');
INSERT INTO `user19` VALUES ('  `address_label` tinyint DEFAULT \'0\' COMMENT \'地址标签\',');
INSERT INTO `user19` VALUES ('  PRIMARY KEY (`id`) USING BTREE');
